def compute(vars):
    nuclear_realized_price_changes = vars["v1"]
    decrease_in_net_revenue = vars["v2"]

    if decrease_in_net_revenue == 0:
        return None

    ratio = nuclear_realized_price_changes / decrease_in_net_revenue
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "nuclear_realized_price_changes": nuclear_realized_price_changes,
            "decrease_in_net_revenue": decrease_in_net_revenue,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
